return $input.all().map((item,index)=>{
 const row=item.json;let src;try{src=typeof row.Script==='string'?JSON.parse(row.Script):row.Script;}catch(e){throw new Error('Scene Production: Script must be valid JSON');}
 if(!src||typeof src!=='object'||!Array.isArray(src.scenes)||!src.scenes.length||typeof src.full_voiceover!=='string'||!src.full_voiceover.trim())throw new Error('Scene Production: complete script scenes and full_voiceover required');
 if(typeof src.total_duration_seconds!=='number'||!Number.isFinite(src.total_duration_seconds)||src.total_duration_seconds<=0)throw new Error('Scene Production: total_duration_seconds must be positive');
 let total=0;src.scenes.forEach((s,i)=>{
  if(!s||typeof s!=='object'||(s.scene_id!==i+1&&s.scene_id!=='SCENE_'+String(i+1).padStart(2,'0')))throw new Error('Scene Production: source scene IDs must be sequential');
  if(typeof s.duration_seconds!=='number'||!Number.isFinite(s.duration_seconds)||s.duration_seconds<=0)throw new Error('Scene Production: scene '+(i+1)+' duration_seconds must be positive');
  if(typeof s.voiceover!=='string'||!s.voiceover.trim())throw new Error('Scene Production: source scene '+(i+1)+' narration required');
  if(s.dialogue!==undefined&&(!Array.isArray(s.dialogue)||s.dialogue.some(v=>typeof v!=='string')))throw new Error('Scene Production: source dialogue must be exact string lines');
  total+=s.duration_seconds;
 });
 if(Math.abs(total-src.total_duration_seconds)>1e-9)throw new Error('Scene Production: source durations do not cover total_duration_seconds');
 const normalize=s=>s.replace(/\s+/g,' ').trim();
 if(normalize(src.full_voiceover)!==normalize(src.scenes.map(s=>s.voiceover).join(' ')))throw new Error('Scene Production: source scenes do not cover full narration');
 return {json:{...row,_aiStartedAt:Date.now()},pairedItem:{item:index}};
});

const sample={"project": "AI That Can Build Its Own Workflow", "format": "youtube_short", "aspect_ratio": "9:16", "scenes": [{"scene_id": "SCENE_01", "duration": "0-3", "type": "image", "scene": "...", "visual": "...", "prompt": "...", "voiceover": "...", "on_screen_text": "...", "sound": "..."}]};
function check(value,shape,path){
 if(Array.isArray(shape)){if(!Array.isArray(value))throw new Error(path+' must be an array');if(shape.length&&value.length===0&&path.endsWith('scenes'))throw new Error(path+' must not be empty');if(shape.length)for(let i=0;i<value.length;i++)check(value[i],shape[0],path+'['+i+']');return;}
 if(shape&&typeof shape==='object'){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(path+' must be an object');for(const k of Object.keys(shape)){if(!Object.prototype.hasOwnProperty.call(value,k))throw new Error(path+'.'+k+' required; no synthesized defaults');check(value[k],shape[k],path+'.'+k);}return;}
 if(typeof value!==typeof shape||(typeof value==='number'&&!Number.isFinite(value)))throw new Error(path+' has invalid type');
}
return $input.all().map((item,index)=>{
 const start=$('Start AI Timing').item.json._aiStartedAt;
 let valid=true,error='';try{check(item.json.output,sample,'output');
 const o=item.json.output;let src=$('Start AI Timing').item.json.Script;if(typeof src==='string')src=JSON.parse(src);
 if(!src||!Array.isArray(src.scenes)||!src.full_voiceover)throw new Error('Complete source script object required for coverage validation');
 if(o.format!=='youtube_short'||o.aspect_ratio!=='9:16'||o.scenes.length!==src.scenes.length)throw new Error('Full script scene/format coverage mismatch');
 let cursor=0;for(let i=0;i<o.scenes.length;i++){const c=o.scenes[i],s=src.scenes[i];if(c.scene_id!=='SCENE_'+String(i+1).padStart(2,'0'))throw new Error('Scene IDs/order invalid');if(c.voiceover!==s.voiceover)throw new Error('Source narration was changed');const m=/^\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*$/.exec(String(c.duration));if(!m||Number(m[1])!==cursor||Number(m[2])-Number(m[1])!==s.duration_seconds||Number(m[2])<=Number(m[1]))throw new Error('Source scene timing changed');cursor=Number(m[2]);if(!['text_to_image','image_to_video','flf_to_video'].includes(c.generation_type??c.type))throw new Error('Unsupported scene generation type');}
 if(cursor!==src.total_duration_seconds)throw new Error('Scene timing does not cover full script');

if(new Set(Object.keys(o)).size!==4 || Object.keys(o).some(k=>!['project','format','aspect_ratio','scenes'].includes(k)))throw new Error('Unexpected scene output top-level fields');
for(let i=0;i<o.scenes.length;i++){
 const c=o.scenes[i],s=src.scenes[i];
 const keys=['scene_id','duration','type','scene','visual','prompt','voiceover','on_screen_text','sound','dialogue','sound_effects','music'];
 if(keys.some(k=>!Object.prototype.hasOwnProperty.call(c,k))||Object.keys(c).some(k=>!keys.includes(k)))throw new Error('Scene '+c.scene_id+' fields differ from contract');
 if(!Array.isArray(c.dialogue)||c.dialogue.some(v=>typeof v!=='string')||JSON.stringify(c.dialogue)!==JSON.stringify(s.dialogue??[]))throw new Error('Scene '+c.scene_id+' source dialogue was changed');
 if(!Array.isArray(c.sound_effects)||c.sound_effects.some(v=>typeof v!=='string')||typeof c.music!=='string')throw new Error('Invalid scene audio fields');
 if(c.type==='text_to_image'&&(c.sound!==''||c.sound_effects.length||c.music!==''))throw new Error('Image scene '+c.scene_id+' must have no audio');
 if(Array.isArray(s.on_screen_text)&&s.on_screen_text.some(t=>!c.on_screen_text.includes(t)))throw new Error('Source overlay text was omitted');
 if(c.dialogue.some(t=>!c.on_screen_text.includes(t)))throw new Error('Dialogue captions were omitted');
}

if(item.json.output.full_voiceover!==undefined&&!item.json.output.full_voiceover.trim())throw new Error('full_voiceover is empty');}catch(e){valid=false;error=e.message;}
 const row=$('Capture Acquired Lock').item.json;
 return {json:{...item.json,_aiMetric:{JobID:String(row.JobID??row._context.currentId),Task:String($workflow.name),ExecutionID:String($execution.id),DurationMs:Math.max(0,Date.now()-start),ValidOutput:valid,Error:error}},pairedItem:{item:index}};
});
